/**
 * Everyone who has taken part in an issue: its author, its assignee, and the
 * authors of its live comments. Removed or suspended members are dropped, so
 * the strip never shows someone who can no longer see the org.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const candidates = new Set<UserId>([
    issue.authorId,
    ...(issue.assigneeId === null ? [] : [issue.assigneeId]),
    ...(await commentRepo.listCommentAuthorIds(orgId, issueId)),
  ]);

  const participants: UserId[] = [];
  for (const userId of candidates) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member?.status === "active") participants.push(userId);
  }
  return participants;
}

